import java.util.*;

class Solution {
  public boolean possibleToStamp(int[][] grid, int h, int w) {
    int m = grid.length, n = grid[0].length;
    int[][] ps = new int[m + 1][n + 1];
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++)
        ps[i + 1][j + 1] = grid[i][j] + ps[i][j + 1] + ps[i + 1][j] - ps[i][j];
    int[][] d = new int[m + 1][n + 1];
    for (int i = 0; i + h <= m; i++)
      for (int j = 0; j + w <= n; j++)
        if (ps[i + h][j + w] - ps[i][j + w] - ps[i + h][j] + ps[i][j] == 0) {
          d[i][j]++;
          d[i + h][j]--;
          d[i][j + w]--;
          d[i + h][j + w]++;
        }
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++) {
        d[i][j] +=
            (i > 0 ? d[i - 1][j] : 0)
                + (j > 0 ? d[i][j - 1] : 0)
                - (i > 0 && j > 0 ? d[i - 1][j - 1] : 0);
        if (grid[i][j] == 0 && d[i][j] == 0) return false;
      }
    return true;
  }
}
